    98→/// Validate a batch of blob-commitment-proof triplets from multiple `BlobSidecars`.
    99→pub fn validate_blobs<E: EthSpec>(
   100→    kzg: &Kzg,
   101→    expected_kzg_commitments: &[KzgCommitment],
   102→    blobs: Vec<&Blob<E>>,
   103→    kzg_proofs: &[KzgProof],
